(() => {
 'use strict';
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
 const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const fine=matchMedia('(hover: hover) and (pointer: fine)').matches;
 const tabs=$$('[data-explore]'),panels=$$('.explorer-panel');
 function activate(tab,focus=false){tabs.forEach(t=>{const on=t===tab;t.classList.toggle('is-active',on);t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;});panels.forEach(p=>{const on=p.id===tab.getAttribute('aria-controls');p.hidden=!on;p.classList.toggle('is-active',on);});if(focus)tab.focus();}
 tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activate(tab));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowDown'||e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowUp'||e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();activate(tabs[next],true);}});});
 if(tabs.length)activate(tabs[0]);
 if(!reduce&&'IntersectionObserver' in window){const io=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('art-in');io.unobserve(entry.target);}}),{threshold:.08,rootMargin:'0px 0px -20px 0px'});$$('.section-heading,.manifesto-new h2,.manifesto-bottom,.color-story-copy h2,.color-story-copy>p,.team-story,.editorial-grid>div,.editorial-grid>figure,.text-editorial-grid,.closing h2,.care-grid article,.option-grid article').forEach((el,i)=>{el.classList.add('art-reveal');el.style.setProperty('--reveal-delay',(i%3)*55+'ms');io.observe(el);});}
 if(fine&&!reduce){let pending=false,px=-500,py=-500;const root=document.documentElement,orbit=$('.cursor-orbit');document.addEventListener('pointermove',e=>{px=e.clientX;py=e.clientY;if(pending)return;pending=true;requestAnimationFrame(()=>{root.style.setProperty('--pointer-x',px+'px');root.style.setProperty('--pointer-y',py+'px');pending=false;});},{passive:true});
 $$('.button').forEach(btn=>{btn.addEventListener('pointermove',e=>{const r=btn.getBoundingClientRect();btn.style.setProperty('--bx',((e.clientX-r.left-r.width/2)*.045)+'px');btn.style.setProperty('--by',((e.clientY-r.top-r.height/2)*.07)+'px');});btn.addEventListener('pointerleave',()=>{btn.style.setProperty('--bx','0px');btn.style.setProperty('--by','0px');});btn.addEventListener('click',e=>{const r=btn.getBoundingClientRect(),ripple=document.createElement('span');ripple.className='button-ripple';ripple.style.setProperty('--rx',(e.clientX?e.clientX-r.left:r.width/2)+'px');ripple.style.setProperty('--ry',(e.clientY?e.clientY-r.top:r.height/2)+'px');ripple.setAttribute('aria-hidden','true');btn.append(ripple);ripple.addEventListener('animationend',()=>ripple.remove(),{once:true});});});
 $$('.gallery-open').forEach(el=>{el.addEventListener('pointerenter',()=>orbit?.classList.add('active'));el.addEventListener('pointerleave',()=>orbit?.classList.remove('active'));el.addEventListener('click',()=>orbit?.classList.remove('active'));});
 $$('.explorer-image').forEach(el=>el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.style.setProperty('--mx',((e.clientX-r.left)/r.width*100)+'%');el.style.setProperty('--my',((e.clientY-r.top)/r.height*100)+'%');}));
 const scene=$('.hero-photo-scene>img');if(scene){let scrolling=false;addEventListener('scroll',()=>{if(scrolling)return;scrolling=true;requestAnimationFrame(()=>{scene.style.translate='0 '+Math.min(scrollY*.055,40)+'px';scrolling=false;});},{passive:true});}
 }
})();
